-- รายชื่อ Senior ผู้ประเมิน
insert into public.senior_names(name) values
  ('นางสาวณัฏฐา บัวศรีจันทร์ (แนน)'),
  ('นายธีธัช ทีรฆาภิบาล (เบส)')
on conflict (name) do nothing;

-- เจ้าหน้าที่ Onsite Support (เพิ่มเฉพาะที่ยังไม่มีในรายชื่อ)
insert into public.staff(name)
select v.name from (values
  ('นางพิมพ์มาดา เฮอร์เบิร์ต (พิมพ์)'),
  ('นางสาวจันทร์จิรา กำแพงจันทร์ (มิ้นท์)'),
  ('นางสาวภุรดา วงศ์ตระกูลยนต์ (ออม)'),
  ('นางสาวสราลี พนิตนรากุล (เฟิร์น)'),
  ('นางสาวอิงกร ภู่ประเสริฐ (อิ๊งค์)'),
  ('นายจักรภัทร โมรา (เจ๋ง)'),
  ('นายชัชณรินทร์ ไกรวิทย์ (ฟีฟ่า)'),
  ('นายณัทกฤช ชาญวุฒิธรรม (พฤก)'),
  ('นายนรันดร์ สำราญมนต์ (ฟิล์ม)'),
  ('นายปวริศ พบหิรัญ (โต๊ด)'),
  ('นายเกษมพงศ์ พันธุ์พิพัฒน์ (มาร์ค)')
) as v(name)
where not exists (select 1 from public.staff s where lower(regexp_replace(btrim(s.name),'\s+',' ','g')) = lower(v.name));

insert into public.senior_evaluations(created_at, senior, staff, troubleshooting, accuracy, communication, service_mind, case_handling, housekeeping, comment) values
  ('2026-04-28 14:21:07+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นางสาวสราลี พนิตนรากุล (เฟิร์น)', 5, 5, 5, 5, 5, 5, 'ชื่นชมในด้านการ Monitor งานและการใช้คำในการตอบคำถามเจ้าหน้าที่ ตม. หรือประสานงานกับเจ้าหน้าที่ SKY ICT / สามารถแนะนำเคสได้อย่างรวดเร็ว และถูกต้อง'),
  ('2026-04-30 15:25:33+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นางสาวภุรดา วงศ์ตระกูลยนต์ (ออม)', 4, 4, 4, 4, 4, 4, 'น้องทำงานได้ดี แต่บางครั้งอาจจะไม่ค่อยมั่นใจ'),
  ('2026-05-25 17:36:28+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายจักรภัทร โมรา (เจ๋ง)', 4, 4, 4, 4, 3, 3, '1. วันนี้ได้เข้าไปแจ้งให้เจ้าหน้าที่สอบถามข้อมูลกับน้อง OSO ขณะที่นั่งอยู่ ยังไม่พบเจ้าหน้าที่สอบถามกับน้องนะคะ 2.การติดตามหรือการส่งต่อน้องทำได้ดี สอบถามเรื่อง Deploy TDAC น้องทราบว่าต้องดำเนินการอย่างไรสำหรับรอบนี้ 3. เรื่องการรักษาความสะอาดยังให้พอใช้เนื่องจากไปกินข้าวแล้วพบว่าน้องไม่เก็บผ้าห่มที่นำออกมาให้เรียบร้อย และไม่พกโทรศัพท์ OSO ติดตัวไป (อาจจะเพราะคิดว่ามีคนอยู่)'),
  ('2026-05-29 17:21:25+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นายปวริศ พบหิรัญ (โต๊ด)', 3, 4, 3, 4, 3, 4, '1. การวิเคราะห์และแก้ไขปัญหา (Troubleshooting Skill) - ซักถามข้อมูลเพิ่มเติมได้ตรงจุด = พอใช้ ถามซ้ำหลายรอบ จับจุดที่ควรจะถามข้อมูลเพิ่มยังไม่ค่อยถูกต้อง - วิเคราะห์ปัญหาเป็นขั้นตอน ไม่ข้ามขั้น = ทำได้พอใช้ถึงดี - แยกแยะอาการ (Symptom) กับสาเหตุ (Cause) ได้ = พอใช้ เพราะยังคงใช้เวลานาน กว่าจะแยกว่าเป็นปัญหาที่เกิดจากสาเหตุใด แม้เคสที่ค่อนข้างง่าย 67940 เรื่องการ Log-in โทรศัพท์ไม่ได้ ที่ใช้เวลาแยกแยะนาน ทั้ง ๆ ที่เกิดจากเจ้าหน้าที่กรอกรหัส CISCO ผิด - เลือกแนวทางแก้ไขที่เหมาะสมกับสถานการณ์ = พอรู้สาเหตุแล้วสามารถทำได้ ดี - มีการทดสอบหรือยืนยันผลหลังแก้ไข = ทำได้ดีตามมาตรฐาน 2. ความถูกต้องของการแก้ไขปัญหา - แก้ไขปัญหาได้ตรงจุด ไม่ใช่แค่แก้ปลายเหตุ = พอใช้ อ้างอิงเคส 67937/67945 ที่ใช้เวลานานเพราะน้องยังงมหาสาเหตุและแนวทางแก้ไข/คำตอบ - ใช้มาตรฐานหรือ Best Practice ขององค์กร = ดี - ผลลัพธ์หลังแก้ไขสามารถใช้งานได้จริง = ดี - มีการตรวจสอบความถูกต้องก่อนส่งมอบงาน = ดี 3. การสื่อสารกับเจ้าหน้าที่ผู้ใช้งาน - อธิบายปัญหาและวิธีแก้ไขเป็นภาษาที่เข้าใจง่าย = พอใช้ ไม่สามารถอธิบายได้อย่างกระจ่างในทีแรก ทำให้เจ้าหน้าที่ ตม. ยังคงไม่เคลียร์กับข้อมูลที่น้องแจ้ง - เลือกใช้คำพูดเหมาะสมกับระดับผู้ใช้งาน (Technical / Non-technical) = ดี - มีการอัปเดตสถานะงานอย่างสม่ำเสมอ = พอใช้ ใช้เวลานาน - รับฟังและตอบคำถามผู้ใช้งานอย่างครบถ้วน = พอใช้ ต้องกลับไปสอบถามข้อมูลเพิ่มกับ ตม. อยู่บ่อยครั้ง - สื่อสารอย่างชัดเจน ไม่กำกวม = พอใช้ อธิบายยังไม่เคลียร์ ทางซีเนียร์จึงช่วยพูดให้ 4. มารยาทและการให้บริการ (Service Mind) = ดี 5. ความถูกต้องในการเปิด / ปิดเคส = พอใช้ เพราะมีเปิดเคสแล้วข้อมูลยังไม่ครบถ้วน และปิดเคสช้า คือ TDAC-94 PM แจ้งปิดเคสเวลา 11:38 แต่ปิดเคสประมาณ 17:00 6. การจัดเก็บเอกสาร อุปกรณ์และการรักษาความสะอาด = ดี'),
  ('2026-05-29 17:28:13+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายปวริศ พบหิรัญ (โต๊ด)', 3, 3, 3, 4, 3, 4, 'หลักๆแล้วน้องยังจับประเด็นปัญหาที่เจ้าหน้าที่แจ้งปัญหายังไม่ได้แบบชัดเจน ต้องมีการสอบถามข้อมูลเจ้าหน้าที่อยู่บ่อยครั้ง จากที่ไปตรวจสอบการทำงานพบลักษณะแบบนี้ทั้ง 3 เคส'),
  ('2026-06-11 14:55:45+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นางสาวอิงกร ภู่ประเสริฐ (อิ๊งค์)', 5, 5, 5, 5, 5, 5, 'น้องจัดเก็บอุปกรณ์ได้สะอาดเรียบร้อย การรับแจ้งปัญหาสามารถอธิบายเจ้าหน้าที่ได้อย่างชัดเจนและมีการอ้างอิงแหล่งที่มาได้ถูกต้อง'),
  ('2026-06-11 16:28:10+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นางสาวอิงกร ภู่ประเสริฐ (อิ๊งค์)', 5, 5, 5, 5, 5, 5, '- อยู่ในระดับดีเยี่ยมทุกหัวข้อ สามารถดำเนินงาน OSO ได้เกินมาตรฐานที่ตั้งไว้ - แม้จะได้รับคำถามที่ไม่ค่อยได้พบบ่อย แต่ก็สามารถวิเคราะห์คำถาม และแนะนำเจ้าหน้าที่ ตม. ได้ถูกต้อง และละเอียด ทำให้เจ้าหน้าที่ ตม. เข้าใจได้ - สื่อสารกับเจ้าหน้าที่ผู้ใช้งานระบบได้อย่างสุภาพ และแสดงความตั้งใจช่วยเหลือ - อาจมีเรื่องการแก้ไข Detail ในการแจ้งเปิดเคสให้เป็นไปตามรูปแบบของทาง CSC เล็กน้อย แต่เนื้อหาถูกต้องแล้ว - การรักษาความสะอาด ดีเยี่ยม ขอบคุณครับ'),
  ('2026-06-22 16:27:59+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นางพิมพ์มาดา เฮอร์เบิร์ต (พิมพ์)', 5, 5, 5, 5, 5, 5, 'โดยรวมดีเยี่ยมทุกหัวข้อ ในช่วงเวลาที่ไป Audit มีเคส 68350 (เปลี่ยนหลอดไฟ) ก็สามารถจัดการได้ถูกต้อง รวมถีงช่วย correct ข้อมูลที่ CSC ส่งเปิดเคสมาผิดด้วย // ส่วนการส่งต่อเคส สามารถส่งต่อได้ครบถ้วน สื่อสารได้เข้าใจดีครับ มีการให้เจ้าหน้าที่สแกน QR ประเมินเคสตามปกติ'),
  ('2026-07-23 16:47:05+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายณัทกฤช ชาญวุฒิธรรม (พฤก)', 5, 5, 4, 5, 4, 5, 'น้องสามารถรับเคสและเปิดได้ดี แต่เรื่องการพูดยังไม่ค่อยชัดเจนเท่าไหร่ อาจจะเพราะเพิ่งเข้า OSO แต่โดยรวมทำงานได้ดี'),
  ('2026-07-28 15:31:31+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นางสาวจันทร์จิรา กำแพงจันทร์ (มิ้นท์)', 4, 5, 5, 5, 4, 5, '1. การวิเคราะห์และแก้ไขปัญหา (Troubleshooting Skill) และ 5. ความถูกต้องในการเปิด / ปิดเคส = ยังต้องปรับปรุงเพิ่มเติมให้ดีกว่านี้ เนื่องจากยังเป็นพนักงานใหม่ประสบการณ์ยังไม่มาก แต่ทำได้ในระดับ "ดี" ตามที่เคยสอนงานไว้ครับ'),
  ('2026-07-28 15:33:29+07', 'นายธีธัช ทีรฆาภิบาล (เบส)', 'นายณัทกฤช ชาญวุฒิธรรม (พฤก)', 5, 5, 5, 5, 3, 5, '5. ความถูกต้องในการเปิด / ปิดเคส = ยังนำคำถามคำตอบมาเปิดเคสได้ไม่ค่อยตรงประเด็นเท่าที่ควร (อาจสับสนว่าควรเปิดเคสอย่างไร) มีแก้ไขเคสหลายครั้ง แต่ยังสามารถตอบเจ้าหน้าที่ ตม. ได้ถูกต้องอยู่ครับ (แจ้งพฤกให้ทราบจุดที่ผิดแล้ว))'),
  ('2026-08-04 18:56:04+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายนรันดร์ สำราญมนต์ (ฟิล์ม)', 5, 5, 5, 5, 5, 5, 'ประเมินในส่วนของการเปิดปิดเคสของ OSO/2 น้องสามารถทำได้ดีและตอบกลับภายในเวลาที่กำหนด แก้ไขปัญหาเฉพาะหน้าได้ดี เนื่องจากมีเครื่อง Kiosk TDAC ใช้งานไม่ได้ น้องสามารถตรวจสอบหน้างานและรายงานผลได้ทันที'),
  ('2026-08-18 14:18:53+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายเกษมพงศ์ พันธุ์พิพัฒน์ (มาร์ค)', 3, 3, 4, 5, 4, 5, 'น้องเจอคำถามเรื่องสายการบินไม่สาามารถ Check-in ได้ เนื่องจากเป็นเที่ยวบินใหม่ เจ้าหน้าที่ตม.ถามว่าให้ติดต่อไปที่ CSC ได้เลยหรือไม่ น้องยังตอบได้ไม่ชัดเจน ยังต้องมีการช่วยน้องตอบในคำถามและเสริมให้เจ้าหน้าที่ตม.เพิ่มเติม'),
  ('2026-09-02 17:14:24+07', 'นางสาวณัฏฐา บัวศรีจันทร์ (แนน)', 'นายชัชณรินทร์ ไกรวิทย์ (ฟีฟ่า)', 4, 4, 4, 5, 4, 5, 'จากการที่ไปตรวจระบบด้วย น้องสามารถทำงานได้ดี มีระเบียบและรู้จักเข้าหาเจ้าหน้าที่ ยิ้มแย้มแจ่มใสดี นอกเหนือจากนี้น้องยังให้คำปรึกษาเกี่ยวกับการเปิดเคสให้กับ OSO อีกคนได้ดี')
on conflict do nothing;
